def edit(a, b):
    d = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        prev, d[0] = d[0], i
        for j, cb in enumerate(b, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j-1] + 1, prev + (ca != cb))
    return d[-1]

truth = "홍길동 900101-1234567"
for name, pred in [("2단계 OCR", "홍길동 900101-1234561"),
                   ("VLM", "홍길동 900101-1234567 서울")]:
    print(f"{name}: CER {edit(truth, pred) / len(truth):.3f}")
# 2단계 OCR: CER 0.056
# VLM: CER 0.167
